import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> with SingleTickerProviderStateMixin {
  int _selectedIndex = 0;

  bool _isRefreshing = false;
  late final AnimationController _refreshController;

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(),
    NewsListPage(),
    ProfilePage(),
  ];

  @override
  void initState() {
    super.initState();
    _initAnimation();
  }

  @override
  void dispose() {
    _refreshController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _refreshController = AnimationController(
      duration: const Duration(milliseconds: 600),
      vsync: this,
    );
  }

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
      _isRefreshing = false;
    });
  }

  Future<void> _refreshAll() async {
    if (_isRefreshing) return;

    setState(() => _isRefreshing = true);

    final CurrencyRepository currencyRepo = context.read<CurrencyRepository>();
    final NewsRepository newsRepo = context.read<NewsRepository>();

    await Future.wait<void>([
      currencyRepo.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
        return currencyRepo.saveCurrencyList(page.items);
      }),
      newsRepo.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]);

    if (mounted) {
      setState(() => _isRefreshing = false);
      _refreshController.forward(from: 0.0);
    }
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: currentPage,
      floatingActionButton: AnimatedBuilder(
        animation: _refreshController.view,
        builder: (BuildContext context, Widget? child) {
          return Transform.scale(
            scale: _isRefreshing ? 1.0 : 0.85,
            child: RotationTransition(
              turns: _refreshController.view,
              child: FloatingActionButton.extended(
                onPressed: _isRefreshing ? null : _refreshAll,
                label: Text(loc.refreshAll),
                icon: const Icon(Icons.sync),
              ),
            ),
          );
        },
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: const Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: [
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            BottomNavigationBarItem(
              icon: const Icon(Icons.person),
              label: loc.profile,
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}

